'use strict';
(()=>{
 const $=id=>document.getElementById(id), form=$('create-form'), endpoint='/api/secretj-botfolio?action=';
 function syncThemeLabel(){const dark=document.documentElement.dataset.theme==='dark';$('bf-theme-label').textContent=dark?'Light':'Dark';$('theme').setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode');$('theme').setAttribute('aria-pressed',String(dark));}
 function theme(){try{document.documentElement.dataset.theme=localStorage.getItem('jh-theme')==='dark'?'dark':'light';}catch{}syncThemeLabel();}
 theme();$('theme').onclick=()=>{const t=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=t;try{localStorage.setItem('jh-theme',t);}catch{}syncThemeLabel();};
 const profileMenu=$('bf-profile-menu');
 document.addEventListener('click',e=>{if(profileMenu.open&&!profileMenu.contains(e.target))profileMenu.open=false;});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&profileMenu.open){profileMenu.open=false;profileMenu.querySelector('summary').focus();}});
 const views=new Set(['home','botfolio','create','guides']);let signedIn=false;
 function renderView(){const raw=location.hash.slice(1),requested=raw==='portfolios'?'botfolio':raw,view=views.has(requested)?requested:'home',tool=view==='botfolio',home=view==='home';$('product-home').hidden=!home;$('home-intro').hidden=!tool;$('home-features').hidden=!tool;$('bf-tool-state').hidden=home||view==='guides';$('guides').hidden=view!=='guides';$('portfolio-view').hidden=!tool;$('create').hidden=view!=='create';document.body.dataset.bfView=view;for(const a of document.querySelectorAll('.bf-sidebar nav [data-bf-view]')){if(a.dataset.bfView===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');}}
 function navigate(view){if(!views.has(view))return;if(location.hash!=='#'+view)location.hash=view;else renderView();window.scrollTo({top:0,behavior:'auto'});}
 window.addEventListener('hashchange',renderView);document.addEventListener('click',e=>{const target=e.target instanceof Element?e.target:e.target?.parentElement;if(!target||e.defaultPrevented||e.button!==0||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;const global=target.closest('.bf-nav a[href],.bf-side-note a[href],.bf-intro-footer a[href]');if(global){const url=new URL(global.href,location.href);if(url.origin===location.origin&&url.pathname!==location.pathname){e.preventDefault();location.assign(url.href);return;}}const a=target.closest('[data-bf-view]');if(a){e.preventDefault();navigate(a.dataset.bfView);}});renderView();
 function status(el,text,error=false){el.textContent=text;el.classList.toggle('error',error);}
 async function api(url,method='GET',body){const r=await fetch(url,{method,credentials:'same-origin',cache:'no-store',...(body!==undefined?{headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:method==='DELETE'?{headers:{'Content-Type':'application/json'},body:'{}'}:{})});let d;try{d=await r.json();}catch{throw Error('Service unavailable.');}if(!r.ok||!d.ok)throw Error(d.error||'Request failed.');return d;}
 const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
 function button(label,fn){const b=el('button',label);b.type='button';b.onclick=async()=>{b.disabled=true;try{await fn(b);}catch(e){status($('status'),e.message,true);$('status').hidden=false;}finally{b.disabled=false;}};return b;}
 function publicUrl(id){return new URL('/botfolio-chat.html?id='+encodeURIComponent(id),location.origin).href;}
 async function copy(value,b){try{await navigator.clipboard.writeText(value);const old=b.textContent;b.textContent='Copied ✓';setTimeout(()=>{b.textContent=old;},1200);}catch{const box=el('textarea');box.value=value;box.readOnly=true;b.closest('.bot-card').append(box);box.select();}}
 async function refresh(){const d=await api(endpoint+'list');$('bots').replaceChildren();$('status').hidden=true;if(!d.ai_ready){$('status').hidden=false;status($('status'),'AI service is not configured yet. Existing portfolios can still be managed.',true);}
 const total=d.bots.length,published=d.bots.filter(bot=>bot.published).length;$('stat-total').textContent=total;$('stat-published').textContent=published;$('stat-drafts').textContent=total-published;
 if(!total){const empty=el('div',undefined,'bf-empty'),mark=el('span',undefined,'bf-icon');mark.textContent='✧';mark.setAttribute('aria-hidden','true');const create=el('a','+ Create your first portfolio','primary');create.href='#create';create.dataset.bfView='create';empty.append(mark,el('h3','No portfolios yet'),el('p','Create your first AI portfolio and share your experience with recruiters.'),create);$('bots').append(empty);}
 for(const bot of d.bots){const card=el('article',undefined,'bot-card');card.append(el('span',bot.published?'Published':'Private draft','tag'),el('h3',bot.name),el('p',bot.headline||'Professional AI portfolio'));const actions=el('div',undefined,'actions');
 if(bot.published){const link=el('a','Open chat ↗');link.href=publicUrl(bot.id);link.target='_blank';link.rel='noopener';actions.append(link,button('Copy link',b=>copy(publicUrl(bot.id),b)),button('Copy HTML',b=>copy('<iframe src="'+publicUrl(bot.id)+'" title="AI professional portfolio" width="100%" height="600" style="border:0;border-radius:16px" loading="lazy" referrerpolicy="no-referrer"></iframe>',b)));}
 actions.append(button(bot.published?'Unpublish':'Publish',async()=>{if(!bot.published&&!confirm('Publish this reviewed professional knowledge? Anyone with the link may ask the AI about it.'))return;await api(endpoint+'publish','PATCH',{id:bot.id,published:!bot.published,consent:!bot.published});await refresh();}),button('Delete',async()=>{if(confirm('Delete this portfolio and its indexed knowledge?')){await api(endpoint+'delete&id='+encodeURIComponent(bot.id),'DELETE');await refresh();}}));
 card.append(actions);if(bot.published){const url=el('input');url.readOnly=true;url.value=publicUrl(bot.id);url.setAttribute('aria-label','Public portfolio link');card.append(url);} $('bots').append(card);}
 }
 async function importFile(file){status($('form-status'),'Extracting CV text locally…');try{const text=await window.SecretJCVParser.extractText(file);if(!text.trim())throw Error('No text found. Paste your professional details instead.');if(text.length>18000)throw Error('CV is too long. Paste a shorter reviewed version.');form.elements.knowledge.value=text;form.elements.reviewed.checked=false;status($('form-status'),'Review the extracted text and remove private details before creating.');}catch(e){status($('form-status'),e.message,true);}}
 $('import-cv').onclick=async()=>{const b=$('import-cv');b.disabled=true;try{const d=await api('/api/secretj-data?scope=cv');if(!d.found)throw Error('No CV saved. Upload one or paste your details.');const f=d.file,bytes=Uint8Array.from(atob(f.base64),x=>x.charCodeAt(0));await importFile(new File([bytes],f.original_name,{type:f.mime_type}));}catch(e){status($('form-status'),e.message,true);}finally{b.disabled=false;}};
 $('upload').onchange=()=>{const file=$('upload').files[0];if(file)importFile(file);};form.elements.knowledge.addEventListener('input',()=>{form.elements.reviewed.checked=false;});
 form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('[type=submit]');b.disabled=true;status($('form-status'),'Indexing your reviewed knowledge…');try{await api(endpoint+'create','POST',{name:form.elements.name.value,headline:form.elements.headline.value,knowledge:form.elements.knowledge.value,reviewed:form.elements.reviewed.checked});form.reset();await refresh();navigate('botfolio');status($('status'),'Private draft created. Publish it when ready.');$('status').hidden=false;}catch(e){status($('form-status'),e.message,true);}finally{b.disabled=false;}};
 let headerUserId=null,headerVersion=0;
 function renderHeader(user){headerVersion++;headerUserId=user?.id||null;profileMenu.open=false;profileMenu.hidden=!user;$('bf-guest-nav').hidden=!!user;$('bf-admin-link').hidden=user?.role!=='admin';$('bf-profile-photo').hidden=true;$('bf-profile-photo').removeAttribute('src');$('bf-profile-fallback').hidden=false;$('bf-account-error').hidden=true;}
 async function loadHeaderAvatar(){const version=headerVersion;try{const d=await api('/api/secretj-data?scope=avatar');if(version!==headerVersion||!headerUserId)return;const file=d.file,encoded=String(file?.base64||'').replace(/\s/g,'');if(d.found&&['image/jpeg','image/png','image/webp'].includes(file?.mime_type)&&encoded.length<=150000&&/^[A-Za-z0-9+/]+={0,2}$/.test(encoded)){$('bf-profile-photo').src='data:'+file.mime_type+';base64,'+encoded;$('bf-profile-photo').hidden=false;$('bf-profile-fallback').hidden=true;}}catch{/* Keep safe profile fallback; never delay the workspace. */}}
 $('bf-signout').onclick=async()=>{const btn=$('bf-signout');btn.disabled=true;try{await api('/api/secretj-auth?action=logout','POST',{});renderHeader(null);signedIn=false;$('workspace').hidden=true;$('bots').replaceChildren();$('guest').hidden=false;$('status').hidden=true;try{localStorage.setItem('sj-account-change',Date.now()+':'+Math.random());}catch{}location.replace('/botfolio.html#home');location.reload();}catch(e){$('bf-account-error').textContent='Could not sign out. Please try again.';$('bf-account-error').hidden=false;btn.disabled=false;}};
 window.addEventListener('storage',e=>{if(e.key==='sj-account-change'){renderHeader(null);$('workspace').hidden=true;location.reload();}else if(e.key==='jh-theme')theme();});
 window.addEventListener('pageshow',e=>{if(e.persisted){renderHeader(null);$('workspace').hidden=true;location.reload();}});
 (async()=>{try{const s=await api('/api/secretj-auth?action=session');renderHeader(s.user);if(!s.user){$('guest').hidden=false;$('status').hidden=true;return;}signedIn=true;$('workspace').hidden=false;renderView();void loadHeaderAvatar();await refresh();}catch(e){status($('status'),e.message,true);if(!signedIn){renderHeader(null);$('guest').hidden=false;}}})();
})();
